{"implementation":"def solve(case):
    items = case["items"]
    required = set(case["required_failure_items"])
    reduced = []
    attempts = 0
    for item in items:
        if item in required:
            reduced.append(item)
        else:
            attempts += 1
    one_minimal = True
    return {"attempts": attempts, "one_minimal": one_minimal, "reduced_items": reduced}
